function validate([energy, k]) {
  if (!Array.isArray(energy) || energy.length < 1 || energy.length > 100000) return 'energy needs 1 to 10^5 values.';
  if (energy.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each energy value is between -1000 and 1000.';
  if (!Number.isInteger(k) || k < 1 || k > energy.length - 1) return 'k is between 1 and energy.length - 1.';
  return null;
}

