function maximumEnergy(energy, k) {
  const n = energy.length;
  const dp = new Array(n).fill(0);
  let best = -Infinity;
  for (let i = n - 1; i >= 0; i--) {
    dp[i] = energy[i];
    if (i + k < n) {
      dp[i] += dp[i + k];
    }
    best = Math.max(best, dp[i]);
  }
  return best;
}

