function maximumEnergy(energy, k) {
  let best = null;
  for (let start = 0; start < energy.length; start++) {
    let total = 0;
    for (let at = start; at < energy.length; at += k) total += energy[at];
    if (best === null || total > best) best = total;
  }
  return best;
}

