function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 9);
  const span = size === 'large' || rand() < 0.2 ? 1000 : 10;
  const energy = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  // Small steps give long chains; any step up to n - 1 is allowed.
  const k = rand() < 0.5 ? 1 + Math.floor(rand() * Math.min(5, n - 1)) : 1 + Math.floor(rand() * (n - 1));
  return [energy, k];
}
